import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as RadioGroup from "../../ui/shadcn-radio-group";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const optionView = (
  value: string,
  selected: boolean,
  disabled: boolean
): Html => {
  const h = html<Message>();

  return h.div(
    [
      h.Class("flex items-center gap-3"),
      ...(disabled ? [h.DataAttribute("disabled", "")] : []),
    ],
    [
      h.button(
        [
          h.Type("button"),
          h.Role("radio"),
          h.AriaChecked(selected),
          h.AriaLabel(value),
          ...(disabled ? [h.Disabled(true)] : []),
        ],
        [selected ? RadioGroup.checkIcon() : RadioGroup.checkPlaceholder()]
      ),
      h.span([h.Class(RadioGroup.shadcnRadioGroupLabelClasses)], [value]),
    ]
  );
};

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [
      h.Role("radiogroup"),
      h.AriaLabel("Disabled options"),
      h.Class(RadioGroup.shadcnRadioGroupVerticalClasses),
    ],
    [
      optionView("Disabled", true, true),
      optionView("Option 2", false, false),
      optionView("Option 3", false, false),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Radio Group Disabled example", () => {
  test("renders the origin disabled radio group demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("radio", { name: "Disabled" })).toBeDisabled(),
      Scene.expect(Scene.role("radio", { name: "Disabled" })).toBeChecked(),
      Scene.expect(Scene.role("radio", { name: "Option 2" })).not.toBeDisabled(),
      Scene.expect(Scene.role("radio", { name: "Option 3" })).toExist()
    );
  });
});
